INSERT INTO pills (id, slug, title, domain, owner_id, origin_site_id, current_version_id, created_at) VALUES
  ('pill-0001', 'chiller-plant-staging-drift', 'Chiller Plant Staging Drift', 'chiller_plant', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pill-0002', 'chiller-condenser-tube-fouling', 'Chiller Condenser Tube Fouling', 'chiller_plant', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pill-0003', 'ahu-night-purge-and-economiser-cycle', 'AHU Night Purge And Economiser Cycle', 'ahu', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pill-0004', 'tenant-comfort-band-review', 'Tenant Comfort Band Review', 'tenant_zone', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pill-0005', 'cooling-tower-water-hygiene-routine', 'Cooling Tower Water Hygiene Routine', 'cooling_tower', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pill-0006', 'vav-box-reheat-valve-calibration', 'VAV Box Reheat Valve Calibration', 'vav_box', 'user-chief', 'site-towerk', NULL, '2026-09-15T01:00:00.000Z'::timestamptz);
INSERT INTO transcript_excerpts (id, pill_id, speaker, text, captured_at, tags, embedding) VALUES
  ('tex-0001', 'pill-0001', 'Daniel Tan', 'The Tower K chiller plant efficiency has gone from 0.6230 to 0.7130 kW per RT over the last fourteen days.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0002', 'pill-0001', 'Daniel Tan', 'The lead chiller is carrying the base load because the staging sequence was left on manual after the September service.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0003', 'pill-0001', 'Daniel Tan', 'Re-sequencing the staging order recovers about 4590 kilowatt hours a day without touching the space setpoint.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0004', 'pill-0001', 'Daniel Tan', 'We measured 76.5 kilowatts of excess demand at 850 RT load.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0005', 'pill-0001', 'Daniel Tan', 'I am not certain whether the condenser tubes are fouled as well, we have not pulled the heads this quarter.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0006', 'pill-0002', 'Daniel Tan', 'The condenser approach temperature on the lag chiller has risen by about two degrees over the quarter.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0007', 'pill-0002', 'Daniel Tan', 'We have not pulled the condenser heads this quarter, so fouling is the working assumption.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0008', 'pill-0003', 'Daniel Tan', 'The level 12 AHU economiser damper has been stuck closed since the damper actuator failed.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0009', 'pill-0003', 'Daniel Tan', 'Running a night purge between one and five in the morning uses outside air instead of chilled water.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0010', 'pill-0003', 'Daniel Tan', 'We measured about 900 kilowatt hours a day of avoidable cooling load.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0011', 'pill-0004', 'Daniel Tan', 'The tenant on level 21 reports the space is too cold against their lease comfort band.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0012', 'pill-0004', 'Daniel Tan', 'Their lease specifies 22.5 to 24.5 degrees during Mon-Fri 08:00 to 19:00.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0013', 'pill-0005', 'Daniel Tan', 'The cooling tower conductivity has been running high and the blowdown schedule has slipped.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0014', 'pill-0005', 'Daniel Tan', 'Biocide dosing is a statutory requirement and must be restored before the next water test.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL),
  ('tex-0015', 'pill-0006', 'Daniel Tan', 'The zone temperature is hunting across about two degrees on the level 19 VAV box.', '2026-09-15T01:00:00.000Z'::timestamptz, '{}'::text[], NULL);
INSERT INTO pill_versions (id, pill_id, version, status, summary, triggers, action_tier, steps, context_requirements, author_id, reviewer_id, review_note, approved_at, supersedes_version_id, created_at) VALUES
  ('pv-0001', 'pill-0001', 1, 'approved', 'Restore the lead/lag staging sequence when plant efficiency drifts upward, before touching any space setpoint.', ARRAY['chiller plant efficiency drift', 'kw per rt rising', 'staging sequence wrong', 'lead lag rotation', 'chiller sequencing', 'plant efficiency degradation', 'chiller drift', 'too hot', 'level 23', 'stuffy']::text[], 'execute_with_approval', '[{"instruction":"Confirm the drift against the 14-day kW/RT trend, not a single reading.","order":1},{"instruction":"Check whether the staging sequence was left on manual after a service.","order":2},{"instruction":"Re-sequence the lead/lag rotation and confirm the lag chiller is loading.","order":3},{"instruction":"Re-measure kW/RT after two full load cycles before closing the case.","order":4},{"instruction":"Do not lower the building-wide chilled-water setpoint to mask the drift.","order":5}]'::jsonb, '{"assetTypes":["chiller_plant","ahu"],"chillerPlant":"CP-1","minGfaSqm":30000,"tariffSgdPerKwh":0.28}'::jsonb, 'user-chief', 'user-reviewer', 'Metrics reproduce from the 14-day telemetry. Options are priced and the setpoint option is correctly demoted.', '2026-09-15T01:00:00.000Z'::timestamptz, NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pv-0002', 'pill-0002', 1, 'approved', 'Diagnose a rising condenser approach temperature and clean the tubes when fouling is confirmed.', ARRAY['condenser approach temperature', 'condenser tube fouling', 'condenser water delta t', 'tube cleaning', 'condenser fouling']::text[], 'execute_with_approval', '[{"instruction":"Trend the condenser approach temperature against the commissioning baseline.","order":1},{"instruction":"Confirm with a water-side delta-T check before booking a shutdown.","order":2},{"instruction":"Clean the tubes and re-baseline the approach temperature afterwards.","order":3}]'::jsonb, '{"assetTypes":["chiller_plant"],"chillerPlant":"CP-1","minGfaSqm":null,"tariffSgdPerKwh":null}'::jsonb, 'user-chief', 'user-reviewer', 'Distinct from the staging pill; triggers do not overlap materially.', '2026-09-15T01:00:00.000Z'::timestamptz, NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pv-0003', 'pill-0003', 1, 'approved', 'Use outside air overnight when the economiser damper is serviceable, to pre-cool the slab without chilled water.', ARRAY['stale air', 'night purge', 'economiser damper', 'fresh air damper stuck', 'ahu ventilation', 'co2 level high']::text[], 'execute_with_approval', '[{"instruction":"Confirm the economiser damper actuator is not stuck before scheduling a purge.","order":1},{"instruction":"Schedule the purge between 01:00 and 05:00, outside lease hours.","order":2},{"instruction":"Verify the damper returns to its scheduled position by 07:00.","order":3}]'::jsonb, '{"assetTypes":["ahu"],"chillerPlant":"CP-1","minGfaSqm":null,"tariffSgdPerKwh":null}'::jsonb, 'user-chief', 'user-reviewer', 'Procedure is comfort-neutral and reversible. Approved.', '2026-09-15T01:00:00.000Z'::timestamptz, NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pv-0004', 'pill-0004', 1, 'approved', 'Resolve overcooling complaints against the contractual lease comfort band before changing any plant setting.', ARRAY['overcooling', 'too cold', 'lease comfort band', 'tenant too cold', 'comfort complaint cold']::text[], 'recommend', '[{"instruction":"Read the lease comfort band and leased hours for the tenant.","order":1},{"instruction":"Compare the measured zone temperature against the band, inside lease hours only.","order":2},{"instruction":"If the zone is inside the band, the complaint is a preference, not a defect.","order":3}]'::jsonb, '{"assetTypes":["tenant_zone","ahu"],"chillerPlant":"CP-1","minGfaSqm":null,"tariffSgdPerKwh":null}'::jsonb, 'user-chief', 'user-reviewer', 'Correctly defers to the lease terms rather than to an energy target.', '2026-09-15T01:00:00.000Z'::timestamptz, NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pv-0005', 'pill-0005', 1, 'approved', 'Restore biocide dosing and blowdown discipline on the cooling tower water circuit.', ARRAY['cooling tower water treatment', 'conductivity high', 'blowdown schedule', 'biocide dosing', 'water hygiene routine']::text[], 'execute_with_approval', '[{"instruction":"Restore the biocide dosing schedule to the statutory interval.","order":1},{"instruction":"Bring blowdown control back within the conductivity setpoint.","order":2},{"instruction":"Book an independent water test before returning the tower to normal service.","order":3}]'::jsonb, '{"assetTypes":["cooling_tower"],"chillerPlant":"CP-1","minGfaSqm":null,"tariffSgdPerKwh":null}'::jsonb, 'user-chief', 'user-reviewer', 'Statutory tier. Must outrank every energy consideration.', '2026-09-15T01:00:00.000Z'::timestamptz, NULL, '2026-09-15T01:00:00.000Z'::timestamptz),
  ('pv-0006', 'pill-0006', 1, 'draft', 'Calibrate the reheat valve on a hunting VAV box before replacing the actuator.', ARRAY['vav reheat valve', 'reheat valve stuck', 'zone temperature hunting']::text[], 'recommend', '[{"instruction":"Stroke the reheat valve and confirm full travel.","order":1},{"instruction":"Re-calibrate the actuator end stops.","order":2}]'::jsonb, '{"assetTypes":["vav_box"],"chillerPlant":"CP-1","minGfaSqm":null,"tariffSgdPerKwh":null}'::jsonb, 'user-chief', NULL, NULL, NULL, NULL, '2026-09-15T01:00:00.000Z'::timestamptz);
INSERT INTO claims (id, pill_version_id, kind, text, source_excerpt_id, confidence) VALUES
  ('claim-0001', 'pv-0001', 'measured', 'Plant efficiency drifted from 0.6230 to 0.7130 kW/RT over 14 days.', 'tex-0001', 0.97),
  ('claim-0002', 'pv-0001', 'derived', 'Re-sequencing the staging order recovers about 4590 kWh per day.', 'tex-0003', 0.8),
  ('claim-0003', 'pv-0001', 'measured', 'Excess demand measured at 76.5 kW at 850 RT load.', 'tex-0004', 0.95),
  ('claim-0004', 'pv-0001', 'unknown', 'Whether the condenser tubes are also fouled this quarter is unverified.', NULL, 0),
  ('claim-0005', 'pv-0002', 'measured', 'Condenser approach temperature rose about 2 °C over the quarter.', 'tex-0006', 0.85),
  ('claim-0006', 'pv-0002', 'assumed', 'Tube fouling is the likely cause of the approach rise.', 'tex-0007', 0.6),
  ('claim-0007', 'pv-0003', 'measured', 'The economiser damper has been stuck closed since the actuator failed.', 'tex-0008', 0.9),
  ('claim-0008', 'pv-0003', 'derived', 'A night purge avoids about 900 kWh of cooling load per day.', 'tex-0010', 0.7),
  ('claim-0009', 'pv-0003', 'unknown', 'Whether the actuator failure affected other AHUs on the same riser is unverified.', NULL, 0),
  ('claim-0010', 'pv-0004', 'measured', 'The lease specifies a comfort band of 22.5–24.5 °C during Mon-Fri 08:00-19:00.', 'tex-0012', 0.99),
  ('claim-0011', 'pv-0004', 'assumed', 'The overcooling is caused by a fixed setpoint rather than by tenant internal load.', 'tex-0011', 0.4),
  ('claim-0012', 'pv-0005', 'measured', 'Cooling tower conductivity is running above the control setpoint.', 'tex-0013', 0.9),
  ('claim-0013', 'pv-0005', 'derived', 'The blowdown schedule has slipped behind the required interval.', 'tex-0013', 0.85),
  ('claim-0014', 'pv-0005', 'unknown', 'Whether the last independent water test returned a positive result is unverified.', NULL, 0),
  ('claim-0015', 'pv-0006', 'measured', 'The zone temperature is hunting across a 2 °C band.', 'tex-0015', 0.75);
INSERT INTO pill_options (id, pill_version_id, label, detail, action_tier, sgd_delta, policy_rank, source_excerpt_id) VALUES
  ('opt-0001', 'pv-0001', 'Re-sequence chiller staging (lead/lag rotation)', 'Restores the intended staging order. Recovers the drift without changing any space condition, so comfort is untouched.', 'execute_with_approval', -1285.2, 2, 'tex-0003'),
  ('opt-0002', 'pv-0001', 'Clean condenser tubes on the lag chiller', 'Fouling is the likely root cause. Cleaning is the durable fix and is scheduled with the next plant shutdown.', 'execute_with_approval', -504, 3, NULL),
  ('opt-0003', 'pv-0001', 'Drop building-wide chilled-water setpoint to 6.0 °C', 'Masks the symptom by over-cooling every floor, raises energy cost, and breaches the energy-target policy tier. Shown so the trade-off is visible, not because it is viable.', 'recommend', 642.6, 3, NULL),
  ('opt-0004', 'pv-0001', 'Night purge via AHU economiser cycle', 'Comfort-neutral pre-cooling between 01:00 and 05:00 using outside air.', 'recommend', -252, 4, NULL),
